window.CODE = Object.assign(window.CODE || {}, {"ch13/agent_basic.py":"\"\"\"The Chapter 9 agent in about ten lines with LangChain's create_agent.\n\ncreate_agent builds the same loop you wrote by hand: call the model, run any tools it asks for,\nfeed the results back, repeat until it answers. (It is built on LangGraph, Chapter 14.)\n\nRun:  python agent_basic.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom clinic_tools import SYSTEM, TOOLS  # noqa: E402\nfrom langchain.agents import create_agent  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nagent = create_agent(model=get_model(), tools=TOOLS, system_prompt=SYSTEM)\n\nif __name__ == \"__main__\":\n    result = agent.invoke({\"messages\": [{\"role\": \"user\", \"content\": \"Is any cardiologist free on Thursday?\"}]})\n\n    # The result holds the whole conversation: the same history your Chapter 9 loop built.\n    for m in result[\"messages\"]:\n        if m.type == \"ai\" and m.tool_calls:\n            for c in m.tool_calls:\n                print(f\"model  -> call {c['name']}({c['args']})\")\n        elif m.type == \"tool\":\n            print(f\"tool   -> {m.content}\")\n        else:\n            print(f\"{m.type:6} -> {m.content}\")\n\n    print(\"\\nTool schema the model saw:\")\n    print(TOOLS[0].tool_call_schema.model_json_schema())\n","ch13/agent_production.py":"\"\"\"A production-shaped LangChain agent: middleware for limits, retries, privacy and human approval.\n\nMiddleware wraps the agent loop, like the hooks in your Chapter 9 harness:\n  before_model / after_model hooks run around each model call; wrap_tool_call runs around each tool.\n\nRun:  python agent_production.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom clinic_tools import SYSTEM, TOOLS  # noqa: E402\nfrom langchain.agents import create_agent  # noqa: E402\nfrom langchain.agents.middleware import (HumanInTheLoopMiddleware, ModelCallLimitMiddleware,  # noqa: E402\n                                         PIIMiddleware, ToolCallLimitMiddleware, ToolRetryMiddleware,\n                                         before_model)\nfrom langgraph.checkpoint.memory import InMemorySaver  # noqa: E402\nfrom langgraph.types import Command  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\n\n@before_model\ndef log_step(state, runtime):\n    \"\"\"A custom hook: runs before every model call. Use it for logging, guards or trimming.\"\"\"\n    print(f\"  [hook] model call with {len(state['messages'])} messages in history\")\n    return None          # returning a dict here would update the state\n\n\nagent = create_agent(\n    model=get_model(),\n    tools=TOOLS,\n    system_prompt=SYSTEM,\n    middleware=[\n        PIIMiddleware(\"email\", strategy=\"redact\", apply_to_input=True),   # emails never reach the model\n        PIIMiddleware(\"phone\", detector=r\"\\b\\d{10}\\b\", strategy=\"mask\"),  # custom detector: 10-digit numbers\n        ModelCallLimitMiddleware(run_limit=6, exit_behavior=\"end\"),       # the loop budget (Chapter 9)\n        ToolCallLimitMiddleware(tool_name=\"request_appointment\", run_limit=1),\n        ToolRetryMiddleware(max_retries=2, backoff_factor=2.0),           # transient tool failures\n        HumanInTheLoopMiddleware(interrupt_on={\"request_appointment\": True,     # writes need a person\n                                               \"get_doctor_schedule\": False}),  # reads run freely\n        log_step,\n    ],\n    checkpointer=InMemorySaver(),   # needed to pause for approval and resume later\n)\n\nif __name__ == \"__main__\":\n    config = {\"configurable\": {\"thread_id\": \"patient-asha-1\"}}\n    msg = (\"Book Dr Rao on Thursday for Asha Verma. My email is asha@example.com \"\n           \"and phone 9876543210.\")\n\n    # stream_mode=\"updates\" shows each step as it happens\n    for update in agent.stream({\"messages\": [{\"role\": \"user\", \"content\": msg}]}, config, stream_mode=\"updates\"):\n        for step, data in update.items():\n            if step == \"__interrupt__\":\n                req = data[0].value[\"action_requests\"][0]\n                print(f\"PAUSED for approval: {req['name']}({req['args']})\")\n            elif data and \"messages\" in data:\n                last = data[\"messages\"][-1]\n                print(f\"{step}: {last.content or last.tool_calls}\")\n\n    print(\"\\nWhat the model received:\", agent.get_state(config).values[\"messages\"][0].content)\n\n    # A staff member approves (could also be \"reject\" with a message, or \"edit\" with new args)\n    print(\"\\nStaff approves...\")\n    result = agent.invoke(Command(resume={\"decisions\": [{\"type\": \"approve\"}]}), config)\n    print(\"Final:\", result[\"messages\"][-1].content)\n","ch13/builtin_tools.py":"\"\"\"Ready-made tools from the LangChain ecosystem. These need extra packages, API keys and internet:\n\n    pip install langchain-tavily wikipedia langchain-experimental\n    TAVILY_API_KEY=...   (free tier at tavily.com)\n\nRun:  python builtin_tools.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom langchain.agents import create_agent  # noqa: E402\nfrom langchain_community.tools import WikipediaQueryRun  # noqa: E402\nfrom langchain_community.utilities import WikipediaAPIWrapper  # noqa: E402\nfrom langchain_tavily import TavilySearch  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\n# Web search built for agents: returns clean text snippets with URLs.\n# include_domains keeps a health agent on trusted sites.\nweb_search = TavilySearch(max_results=3, include_domains=[\"who.int\", \"mohfw.gov.in\", \"cdc.gov\"])\n\n# Wikipedia: good for background facts, never for clinical decisions.\nwikipedia = WikipediaQueryRun(api_wrapper=WikipediaAPIWrapper(top_k_results=1, doc_content_chars_max=1500))\n\n# Python REPL (langchain_experimental.tools.PythonREPLTool) runs ANY code the model writes on your\n# machine. Never give it to an agent that reads untrusted text. If you need calculations, write a\n# small tool that does exactly that calculation, or run code in a sandbox (Chapter 41).\n\nagent = create_agent(get_model(), tools=[web_search, wikipedia],\n                     system_prompt=\"You answer general health-awareness questions for a hospital newsletter. \"\n                                   \"Cite the URL of every fact. Never give personal medical advice.\")\n\nif __name__ == \"__main__\":\n    out = agent.invoke({\"messages\": [{\"role\": \"user\", \"content\": \"What does WHO recommend about dengue prevention at home?\"}]})\n    print(out[\"messages\"][-1].content)\n","ch13/clinic_tools.py":"\"\"\"The Chapter 9 clinic tools, wrapped as LangChain tools.\n\n@tool reads the function name, the docstring and the type hints, and builds the tool schema\nthe model sees. The docstring IS the tool description, so write it for the model.\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nimport clinic  # noqa: E402  (plain Python data and functions from Chapter 9)\nfrom langchain_core.tools import tool  # noqa: E402\n\nSYSTEM = clinic.SYSTEM\n\n\n@tool(parse_docstring=True)\ndef get_doctor_schedule(department: str) -> dict:\n    \"\"\"Look up which doctors in a hospital department see patients on which weekdays.\n    Use this before answering any question about a doctor's availability.\n\n    Args:\n        department: Department name, for example cardiology.\n    \"\"\"\n    return clinic.get_doctor_schedule(department)\n\n\n@tool(parse_docstring=True)\ndef request_appointment(doctor: str, day: str, patient_name: str) -> dict:\n    \"\"\"Create an appointment request for staff to approve. Only use it after the patient has\n    clearly asked to book and has given their name. It does not confirm the booking.\n\n    Args:\n        doctor: Exact doctor name, e.g. Dr Rao.\n        day: Weekday, e.g. Thu.\n        patient_name: The patient's full name.\n    \"\"\"\n    return clinic.request_appointment(doctor, day, patient_name)\n\n\nTOOLS = [get_doctor_schedule, request_appointment]\n","ch13/sql_agent.py":"\"\"\"A SQL agent: answers questions about clinic appointments by writing SQL, safely.\n\nSafety comes from the DATABASE, not from the prompt:\n  1. The connection is opened read-only (mode=ro), so INSERT/UPDATE/DELETE fail at the database.\n  2. Only one SELECT statement is accepted, and results are capped at 50 rows.\n  3. Patient names are not in the table the agent can see (only counts and departments).\n\nRun:  python sql_agent.py\n\"\"\"\nimport random\nimport sqlite3\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nfrom langchain.agents import create_agent  # noqa: E402\nfrom langchain_core.tools import tool  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nDB = HERE / \"clinic.db\"\nMAX_ROWS = 50\n\n\ndef make_db() -> None:\n    \"\"\"Create a small made-up appointments database (synthetic data, no real patients).\"\"\"\n    DB.unlink(missing_ok=True)\n    con = sqlite3.connect(DB)\n    con.execute(\"CREATE TABLE appointments (id INTEGER PRIMARY KEY, doctor TEXT, department TEXT, \"\n                \"day TEXT, status TEXT CHECK (status IN ('booked','completed','no_show','cancelled')))\")\n    rng = random.Random(7)\n    doctors = [(\"Dr Mehta\", \"cardiology\", [\"Mon\", \"Wed\"]), (\"Dr Rao\", \"cardiology\", [\"Thu\", \"Fri\"]),\n               (\"Dr Iyer\", \"orthopaedics\", [\"Tue\", \"Thu\"]), (\"Dr Khan\", \"paediatrics\", [\"Mon\", \"Tue\", \"Fri\"])]\n    rows = []\n    for i in range(1, 201):\n        doc, dept, days = rng.choice(doctors)\n        rows.append((i, doc, dept, rng.choice(days), rng.choices([\"completed\", \"no_show\", \"cancelled\", \"booked\"], [70, 12, 8, 10])[0]))\n    con.executemany(\"INSERT INTO appointments VALUES (?,?,?,?,?)\", rows)\n    con.commit()\n    con.close()\n\n\ndef _connect_read_only():\n    return sqlite3.connect(f\"file:{DB}?mode=ro\", uri=True)\n\n\n@tool\ndef describe_tables() -> str:\n    \"\"\"Show the tables and columns you can query. Call this before writing SQL.\"\"\"\n    with _connect_read_only() as con:\n        return \"\\n\".join(r[0] for r in con.execute(\"SELECT sql FROM sqlite_master WHERE type='table'\"))\n\n\n@tool\ndef run_sql(query: str) -> str:\n    \"\"\"Run ONE read-only SQLite SELECT query and return the rows (max 50).\n\n    Args:\n        query: A single SELECT statement.\n    \"\"\"\n    q = query.strip().rstrip(\";\")\n    if not q.lower().startswith(\"select\") or \";\" in q:\n        return \"Error: only a single SELECT statement is allowed.\"\n    try:\n        with _connect_read_only() as con:\n            cur = con.execute(q)\n            cols = [d[0] for d in cur.description]\n            rows = cur.fetchmany(MAX_ROWS + 1)\n    except sqlite3.Error as exc:\n        return f\"SQL error: {exc}. Check the column names with describe_tables and try again.\"\n    more = \"\\n(more rows not shown)\" if len(rows) > MAX_ROWS else \"\"\n    return \" | \".join(cols) + \"\\n\" + \"\\n\".join(\" | \".join(map(str, r)) for r in rows[:MAX_ROWS]) + more\n\n\nagent = create_agent(get_model(), tools=[describe_tables, run_sql], system_prompt=(\n    \"You answer City Clinic operations questions from the appointments database. \"\n    \"First call describe_tables, then write SQLite SELECT queries with run_sql. \"\n    \"If a query fails, read the error and fix it. Give the final number and the SQL you used.\"))\n\nif __name__ == \"__main__\":\n    make_db()\n    print(\"Write attempt blocked:\", run_sql.invoke({\"query\": \"DELETE FROM appointments\"}))\n    try:\n        _connect_read_only().execute(\"UPDATE appointments SET status='booked'\")\n    except sqlite3.OperationalError as exc:\n        print(\"Database refuses writes too:\", exc)\n\n    out = agent.invoke({\"messages\": [{\"role\": \"user\", \"content\": \"Which doctor had the most no-shows?\"}]})\n    for m in out[\"messages\"][1:]:\n        if m.type == \"ai\" and m.tool_calls:\n            print(\"model ->\", m.tool_calls[0][\"name\"], m.tool_calls[0][\"args\"])\n        elif m.type == \"tool\":\n            print(\"tool  ->\", m.content.replace(\"\\n\", \" / \")[:150])\n        else:\n            print(\"answer->\", m.content)\n","ch13/tools_deep.py":"\"\"\"Tools in depth: validated arguments, tools from existing functions, and errors the model can fix.\n\nRun:  python tools_deep.py\n\"\"\"\nimport sys\nfrom pathlib import Path\nfrom typing import Literal\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch09\"))\nimport clinic  # noqa: E402\nfrom langchain_core.tools import StructuredTool, ToolException, tool  # noqa: E402\nfrom pydantic import BaseModel, Field  # noqa: E402\n\nDay = Literal[\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\"]\n\n\n# 1. A Pydantic args_schema: types, allowed values and limits are checked BEFORE your code runs,\n#    and the descriptions are sent to the model.\nclass AppointmentArgs(BaseModel):\n    doctor: str = Field(description=\"Exact doctor name, e.g. Dr Rao\", pattern=r\"^Dr [A-Z][a-z]+$\")\n    day: Day = Field(description=\"Weekday the doctor works\")\n    patient_name: str = Field(min_length=2, max_length=80)\n\n\ndef _request(doctor: str, day: str, patient_name: str) -> dict:\n    result = clinic.request_appointment(doctor, day, patient_name)\n    if \"error\" in result:\n        # ToolException + handle_tool_error=True: the message goes back to the model as the\n        # tool result, so it can correct itself instead of the whole run crashing.\n        days = result.get(\"available_days\")\n        raise ToolException(result[\"error\"] + (f\" Available days: {', '.join(days)}.\" if days else \"\"))\n    return result\n\n\ndef explain_bad_args(err) -> str:\n    \"\"\"Turn a Pydantic validation error into a short message the model can act on.\"\"\"\n    return \"Invalid arguments: \" + \"; \".join(f\"{'.'.join(map(str, e['loc']))}: {e['msg']}\" for e in err.errors())\n\n\n# 2. StructuredTool.from_function: wrap an existing function without changing it.\nrequest_appointment = StructuredTool.from_function(\n    func=_request, name=\"request_appointment\", args_schema=AppointmentArgs,\n    description=\"Create an appointment request for staff to approve. Does not confirm the booking.\",\n    handle_tool_error=True,             # errors become observations, not crashes\n    handle_validation_error=explain_bad_args,   # bad arguments too, with a useful message\n)\n\n\n# 3. @tool with parse_docstring: argument descriptions come from the Google-style docstring.\n@tool(parse_docstring=True)\ndef opd_fee(visit: Literal[\"new\", \"follow-up\"], days_since_last: int = 0) -> str:\n    \"\"\"Work out the OPD fee for a visit.\n\n    Args:\n        visit: Whether this is a new visit or a follow-up.\n        days_since_last: Days since the last visit to the same doctor.\n    \"\"\"\n    return \"Rs 0 (free follow-up)\" if visit == \"follow-up\" and days_since_last <= 7 else \"Rs 100\"\n\n\nif __name__ == \"__main__\":\n    print(\"Valid call:     \", request_appointment.invoke({\"doctor\": \"Dr Rao\", \"day\": \"Thu\", \"patient_name\": \"Asha Verma\"}))\n    print(\"Wrong day:      \", request_appointment.invoke({\"doctor\": \"Dr Rao\", \"day\": \"Mon\", \"patient_name\": \"Asha Verma\"}))\n    print(\"Invalid args:   \", request_appointment.invoke({\"doctor\": \"rao\", \"day\": \"Sunday\", \"patient_name\": \"A\"}))\n    print(\"Docstring tool: \", opd_fee.invoke({\"visit\": \"follow-up\", \"days_since_last\": 5}))\n    print(\"\\nSchema sent to the model for opd_fee:\")\n    print(opd_fee.tool_call_schema.model_json_schema())\n","common/lc_models.py":"\"\"\"One place to create LangChain chat models and embeddings for every Part C chapter.\n\nLangChain hides the provider differences, so switching OpenAI <-> Anthropic is one line:\n\n    init_chat_model(\"openai:gpt-4.1-mini\")     or     init_chat_model(\"anthropic:claude-haiku-5-5\")\n\nThis helper reads the same .env settings as llm.py (PROVIDER, OPENAI_MODEL, ANTHROPIC_MODEL).\n\n    from lc_models import get_model, get_embeddings\n    model = get_model()                  # a LangChain chat model for your PROVIDER\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\nfrom langchain.chat_models import init_chat_model\nfrom langchain_core.embeddings import Embeddings\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\n\n\ndef get_model(provider: str | None = None, temperature: float = 0, **kwargs):\n    \"\"\"A chat model with sensible production defaults: a timeout and automatic retries.\"\"\"\n    provider = provider or PROVIDER\n    return init_chat_model(f\"{provider}:{MODELS[provider]}\", temperature=temperature,\n                           timeout=float(os.getenv(\"LLM_TIMEOUT\", \"30\")),\n                           max_retries=int(os.getenv(\"LLM_RETRIES\", \"2\")), **kwargs)\n\n\nclass CourseEmbeddings(Embeddings):\n    \"\"\"Wraps llm.embed() (Chapter 6) so LangChain vector stores can use it.\n    EMBEDDINGS=openai uses text-embedding-3-small; EMBEDDINGS=local uses a free local model.\"\"\"\n\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\n        from llm import embed\n        return embed(texts)\n\n    def embed_query(self, text: str) -> list[float]:\n        return self.embed_documents([text])[0]\n\n\ndef get_embeddings() -> Embeddings:\n    return CourseEmbeddings()\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
